using Microsoft.Data.SqlClient; using ProjectTask.DTO; using System.Data;
namespace ProjectTask.DAL;
public class ProjectRepository {
 public async Task<List<Project>> GetAllAsync(){var a=new List<Project>();await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("SELECT MaDuAn,TenDuAn,NgayBatDau,NgayKetThuc,TrangThai FROM DuAn ORDER BY MaDuAn DESC",c);await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())a.Add(new Project{MaDuAn=r.GetInt32(0),TenDuAn=r.GetString(1),NgayBatDau=r.IsDBNull(2)?null:r.GetDateTime(2),NgayKetThuc=r.IsDBNull(3)?null:r.GetDateTime(3),TrangThai=r.IsDBNull(4)?"":r.GetString(4)});return a;}
 public async Task SaveAsync(Project p,bool isNew){await using var c=Db.CreateConnection();await c.OpenAsync();var sql=isNew?"INSERT INTO DuAn(TenDuAn,NgayBatDau,NgayKetThuc,TrangThai) VALUES(@n,@s,@e,@st)":"UPDATE DuAn SET TenDuAn=@n,NgayBatDau=@s,NgayKetThuc=@e,TrangThai=@st WHERE MaDuAn=@id";await using var q=new SqlCommand(sql,c);q.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=p.TenDuAn;q.Parameters.Add("@s",SqlDbType.DateTime).Value=(object?)p.NgayBatDau??DBNull.Value;q.Parameters.Add("@e",SqlDbType.DateTime).Value=(object?)p.NgayKetThuc??DBNull.Value;q.Parameters.Add("@st",SqlDbType.NVarChar,50).Value=p.TrangThai;q.Parameters.Add("@id",SqlDbType.Int).Value=p.MaDuAn;await q.ExecuteNonQueryAsync();}
 public async Task DeleteAsync(int id){await using var c=Db.CreateConnection();await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();try{await using(var q=new SqlCommand("DELETE FROM PhanCong WHERE MaTask IN(SELECT MaTask FROM CongViec WHERE MaDuAn=@id); DELETE FROM CongViec WHERE MaDuAn=@id; DELETE FROM DuAn WHERE MaDuAn=@id",c,(SqlTransaction)tx)){q.Parameters.Add("@id",SqlDbType.Int).Value=id;await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}catch{await tx.RollbackAsync();throw;}}
}
public class MemberRepository {
 public async Task<List<Member>> GetAllAsync(){var a=new List<Member>();await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("SELECT MaThanhVien,HoTen,Email,ChuyenMon FROM ThanhVien ORDER BY HoTen",c);await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())a.Add(new Member{MaThanhVien=r.GetInt32(0),HoTen=r.GetString(1),Email=r.IsDBNull(2)?"":r.GetString(2),ChuyenMon=r.IsDBNull(3)?"":r.GetString(3)});return a;}
}
public class TaskRepository {
 public async Task<List<TaskItem>> GetAllAsync(int projectId=0,string status=""){var a=new List<TaskItem>();await using var c=Db.CreateConnection();await c.OpenAsync();var sql=@"SELECT t.MaTask,t.MaDuAn,t.TenTask,ISNULL(t.MoTa,''),t.HanNop,t.DoUuTien,t.TrangThai,d.TenDuAn,ISNULL(STUFF((SELECT ', '+m.HoTen FROM PhanCong pc JOIN ThanhVien m ON pc.MaThanhVien=m.MaThanhVien WHERE pc.MaTask=t.MaTask FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,2,''),'') FROM CongViec t JOIN DuAn d ON t.MaDuAn=d.MaDuAn WHERE (@p=0 OR t.MaDuAn=@p) AND (@s='' OR t.TrangThai=@s) ORDER BY t.HanNop";await using var q=new SqlCommand(sql,c);q.Parameters.Add("@p",SqlDbType.Int).Value=projectId;q.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())a.Add(new TaskItem{MaTask=r.GetInt32(0),MaDuAn=r.GetInt32(1),TenTask=r.GetString(2),MoTa=r.GetString(3),HanNop=r.IsDBNull(4)?null:r.GetDateTime(4),DoUuTien=r.IsDBNull(5)?"Trung bình":r.GetString(5),TrangThai=r.GetString(6),TenDuAn=r.GetString(7),ThanhVien=r.GetString(8)});return a;}
 public async Task SaveAsync(TaskItem t,bool isNew){await using var c=Db.CreateConnection();await c.OpenAsync();var sql=isNew?"INSERT INTO CongViec(MaDuAn,TenTask,MoTa,HanNop,DoUuTien,TrangThai) VALUES(@p,@n,@m,@h,@u,@s)":"UPDATE CongViec SET MaDuAn=@p,TenTask=@n,MoTa=@m,HanNop=@h,DoUuTien=@u,TrangThai=@s WHERE MaTask=@id";await using var q=new SqlCommand(sql,c);q.Parameters.Add("@p",SqlDbType.Int).Value=t.MaDuAn;q.Parameters.Add("@n",SqlDbType.NVarChar,200).Value=t.TenTask;q.Parameters.Add("@m",SqlDbType.NVarChar,-1).Value=t.MoTa;q.Parameters.Add("@h",SqlDbType.DateTime).Value=(object?)t.HanNop??DBNull.Value;q.Parameters.Add("@u",SqlDbType.NVarChar,20).Value=t.DoUuTien;q.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=t.TrangThai;q.Parameters.Add("@id",SqlDbType.Int).Value=t.MaTask;await q.ExecuteNonQueryAsync();}
 public async Task DeleteAsync(int id){await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("DELETE FROM CongViec WHERE MaTask=@id",c);q.Parameters.Add("@id",SqlDbType.Int).Value=id;await q.ExecuteNonQueryAsync();}
 public async Task UpdateStatusAsync(int id,string status){await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("UPDATE CongViec SET TrangThai=@s WHERE MaTask=@id",c);q.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;q.Parameters.Add("@id",SqlDbType.Int).Value=id;if(await q.ExecuteNonQueryAsync()==0)throw new Exception("Không tìm thấy công việc.");}
 public async Task AssignAsync(int taskId,int memberId){await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("IF NOT EXISTS(SELECT 1 FROM PhanCong WHERE MaTask=@t AND MaThanhVien=@m) INSERT INTO PhanCong(MaTask,MaThanhVien) VALUES(@t,@m)",c);q.Parameters.Add("@t",SqlDbType.Int).Value=taskId;q.Parameters.Add("@m",SqlDbType.Int).Value=memberId;await q.ExecuteNonQueryAsync();}
 public async Task<DataTable> GetOverdueAsync(){var dt=new DataTable();await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand("SELECT t.MaTask,t.TenTask,d.TenDuAn,t.HanNop,t.TrangThai FROM CongViec t JOIN DuAn d ON t.MaDuAn=d.MaDuAn WHERE t.HanNop<GETDATE() AND t.TrangThai<>N'Done' ORDER BY t.HanNop",c);await using var r=await q.ExecuteReaderAsync();dt.Load(r);return dt;}
 public async Task<DataTable> GetStatsAsync(int projectId){var dt=new DataTable();await using var c=Db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand(@"SELECT m.HoTen AS ThanhVien,COUNT(*) AS TongTask,SUM(CASE WHEN t.TrangThai=N'Done' THEN 1 ELSE 0 END) AS TaskDone,CAST(100.0*SUM(CASE WHEN t.TrangThai=N'Done' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0) AS DECIMAL(5,2)) AS TyLeHoanThanh FROM PhanCong pc JOIN ThanhVien m ON pc.MaThanhVien=m.MaThanhVien JOIN CongViec t ON pc.MaTask=t.MaTask WHERE (@p=0 OR t.MaDuAn=@p) GROUP BY m.MaThanhVien,m.HoTen ORDER BY m.HoTen",c);q.Parameters.Add("@p",SqlDbType.Int).Value=projectId;await using var r=await q.ExecuteReaderAsync();dt.Load(r);return dt;}
}
